"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import { Icon } from "@/components/ui/icon"
import { Input } from "@/components/ui/input"
import { Label as FieldLabel } from "@/components/ui/label"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { LABELS, type Label } from "@/components/blocks/kanban-board/components/kanban-board-data"

export function AddNote({ column, onAdd }: { column: string; onAdd: (title: string, label: Label) => void }) {
  const uid = React.useId()
  const [open, setOpen] = React.useState(false)
  const [title, setTitle] = React.useState("")
  const [label, setLabel] = React.useState<Label>("Studio")
  const [error, setError] = React.useState(false)
  const opener = React.useRef<HTMLButtonElement>(null)
  const field = React.useRef<HTMLInputElement>(null)

  React.useEffect(() => {
    if (open) field.current?.focus()
  }, [open])

  const close = () => {
    setOpen(false)
    setTitle("")
    setError(false)
    requestAnimationFrame(() => opener.current?.focus())
  }

  if (!open) {
    return (
      <Button ref={opener} variant="ghost" className="w-full justify-start" onClick={() => setOpen(true)}>
        <Icon name="plus" />
        Add a note<span className="sr-only"> to {column}</span>
      </Button>
    )
  }

  return (
    <form
      className="flex flex-col gap-3 p-1"
      aria-label={`New note in ${column}`}
      noValidate
      onSubmit={(e) => {
        e.preventDefault()
        if (!title.trim()) return setError(true)
        onAdd(title.trim(), label)
        close()
      }}
      onKeyDown={(e) => {
        if (e.key === "Escape" && !e.defaultPrevented) close()
      }}
    >
      <div className="flex flex-col gap-1.5">
        <FieldLabel htmlFor={`${uid}-title`}>What needs doing?</FieldLabel>
        <Input
          ref={field}
          id={`${uid}-title`}
          value={title}
          onChange={(e) => {
            setTitle(e.target.value)
            setError(false)
          }}
          aria-invalid={error ? true : undefined}
          aria-describedby={error ? `${uid}-error` : undefined}
        />
        {error ? (
          <p id={`${uid}-error`} role="alert" className="text-sm text-destructive">
            Write a few words on the note first.
          </p>
        ) : null}
      </div>
      <div className="flex flex-col gap-1.5">
        <FieldLabel htmlFor={`${uid}-label`}>Which pad?</FieldLabel>
        <Select value={label} onValueChange={(v) => setLabel(v as Label)}>
          <SelectTrigger id={`${uid}-label`} size="sm" className="w-full">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {LABELS.map((l) => (
              <SelectItem key={l} value={l}>
                {l}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>
      <div className="flex justify-end gap-2">
        <Button type="button" variant="outline" size="sm" onClick={close}>
          Cancel
        </Button>
        <Button type="submit" size="sm">
          Stick it up
        </Button>
      </div>
    </form>
  )
}

"use client"

import * as React from "react"

import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import { Button } from "@/components/ui/button"
import { Icon } from "@/components/ui/icon"
import { StickyNote, StickyNoteContent, StickyNoteFooter, StickyNoteTitle } from "@/components/ui/sticky-note"
import { cn } from "@/lib/utils"
import { COLUMNS, LABEL_COLOR, type ColumnId, type Note } from "@/components/blocks/kanban-board/components/kanban-board-data"

type Direction = "back" | "forward"

export function NoteCard({
  note,
  dragging,
  onMove,
  onDragStart,
  onDragEnd,
}: {
  note: Note
  dragging: boolean
  onMove: (id: string, to: ColumnId, via: Direction) => void
  onDragStart: (id: string, e: React.DragEvent) => void
  onDragEnd: () => void
}) {
  const at = COLUMNS.findIndex((c) => c.id === note.column)
  const back = COLUMNS[at - 1]
  const forward = COLUMNS[at + 1]
  return (
    <StickyNote
      data-note-id={note.id}
      color={LABEL_COLOR[note.label]}
      done={note.column === "done" ? true : undefined}
      fastener={note.column === "doing" ? "pin" : false}
      seed={note.id}
      draggable
      onDragStart={(e: React.DragEvent) => onDragStart(note.id, e)}
      onDragEnd={onDragEnd}
      className={cn("min-h-0 w-full cursor-grab gap-2 px-4 pt-6 pb-3 active:cursor-grabbing", dragging && "opacity-50")}
    >
      <p className="font-type text-xs text-ink-soft">{note.label}</p>
      <StickyNoteContent>
        <StickyNoteTitle role="heading" aria-level={3} className="text-[1.5rem] leading-[1.05]">
          {note.title}
        </StickyNoteTitle>
        {note.detail ? <p className="mt-1 text-[1.15rem] leading-tight">{note.detail}</p> : null}
      </StickyNoteContent>
      <StickyNoteFooter className="flex items-center gap-2 pt-1">
        <Avatar size="sm" ring="none" aria-hidden="true">
          <AvatarFallback name={note.who} />
        </Avatar>
        <span className="min-w-0 flex-1 truncate">
          {note.who.split(" ")[0]}
          {note.due ? <span className="text-ink-soft"> · due {note.due}</span> : null}
        </span>
        <span className="flex shrink-0 items-center gap-0.5">
          {back ? (
            <Button variant="ghost" size="icon-sm" data-move="back" aria-label={`Move “${note.title}” to ${back.title}`} onClick={() => onMove(note.id, back.id, "back")}>
              <Icon name="arrow-left" />
            </Button>
          ) : null}
          {forward ? (
            <Button variant="ghost" size="icon-sm" data-move="forward" aria-label={`Move “${note.title}” to ${forward.title}`} onClick={() => onMove(note.id, forward.id, "forward")}>
              <Icon name="arrow-right" />
            </Button>
          ) : null}
        </span>
      </StickyNoteFooter>
    </StickyNote>
  )
}

"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import { Paper } from "@/components/ui/paper"
import { Tally } from "@/components/ui/tally"
import { AddNote } from "@/components/blocks/kanban-board/components/kanban-board-add-note"
import { NoteCard } from "@/components/blocks/kanban-board/components/kanban-board-card"
import type { ColumnId, Label, Note } from "@/components/blocks/kanban-board/components/kanban-board-data"

export function Column({
  id,
  title,
  hint,
  notes,
  dragging,
  over,
  onOver,
  onMove,
  onDragStart,
  onDragEnd,
  onDrop,
  onAdd,
  onClear,
}: {
  id: ColumnId
  title: string
  hint: string
  notes: Note[]
  dragging: string | null
  over: boolean
  onOver: (over: boolean) => void
  onMove: (id: string, to: ColumnId, via: "back" | "forward") => void
  onDragStart: (id: string, e: React.DragEvent) => void
  onDragEnd: () => void
  onDrop: (to: ColumnId, e: React.DragEvent) => void
  onAdd: (title: string, label: Label) => void
  onClear?: () => void
}) {
  const headingId = React.useId()
  return (
    <section aria-labelledby={headingId} data-column={id} className="min-w-0">
      <Paper stock="graph" tilt={false} seed={`kanban-${id}`} className="flex h-full flex-col gap-3 p-4">
        <header className="flex items-start gap-2">
          <div className="min-w-0 flex-1">
            <h2 id={headingId} className="font-script text-[1.9rem] leading-none font-bold">
              {title}
            </h2>
            <p className="text-sm text-muted-foreground">{hint}</p>
          </div>
          {onClear && notes.length ? (
            <Button variant="ghost" size="sm" onClick={onClear} aria-label={`Clear the ${notes.length} done ${notes.length === 1 ? "note" : "notes"}`}>
              Clear
            </Button>
          ) : null}
          <Tally count={notes.length} size="md" seed={`kanban-tally-${id}`} label={`${notes.length} ${notes.length === 1 ? "note" : "notes"}`} className="mt-1" />
        </header>
        <div
          data-over={over ? "true" : undefined}
          className="flex min-h-40 flex-1 flex-col gap-4 p-1 data-[over=true]:outline-2 data-[over=true]:outline-offset-2 data-[over=true]:outline-dashed data-[over=true]:outline-ink-you"
          onDragOver={(e) => {
            if (!dragging) return
            e.preventDefault()
            e.dataTransfer.dropEffect = "move"
            if (!over) onOver(true)
          }}
          onDragLeave={(e) => {
            if (!e.currentTarget.contains(e.relatedTarget as Node | null)) onOver(false)
          }}
          onDrop={(e) => {
            e.preventDefault()
            onOver(false)
            onDrop(id, e)
          }}
        >
          {notes.length ? (
            <ul role="list" className="flex flex-col gap-4">
              {notes.map((n) => (
                <li key={n.id}>
                  <NoteCard note={n} dragging={dragging === n.id} onMove={onMove} onDragStart={onDragStart} onDragEnd={onDragEnd} />
                </li>
              ))}
            </ul>
          ) : (
            <p className="py-6 text-center text-sm text-muted-foreground">Nothing here yet. Drop a note, or write a new one.</p>
          )}
        </div>
        <AddNote column={title} onAdd={onAdd} />
      </Paper>
    </section>
  )
}

"use client"

import * as React from "react"

import { Column } from "@/components/blocks/kanban-board/components/kanban-board-column"
import { COLUMNS, notes as sample, TEAM, type ColumnId, type Label, type Note } from "@/components/blocks/kanban-board/components/kanban-board-data"
import { Avatar, AvatarFallback, AvatarGroup } from "@/components/ui/avatar"
import { Sticker } from "@/components/ui/sticker"

export default function KanbanBoard({ as: Root = "main" }: { as?: "main" | "div" } = {}) {
  const [notes, setNotes] = React.useState<Note[]>(sample)
  const [dragging, setDragging] = React.useState<string | null>(null)
  const [over, setOver] = React.useState<ColumnId | null>(null)
  const [message, setMessage] = React.useState("")
  const focus = React.useRef<{ id: string; via: "back" | "forward" | null } | null>(null)
  const board = React.useRef<HTMLDivElement>(null)

  React.useLayoutEffect(() => {
    const target = focus.current
    if (!target) return
    focus.current = null
    const card = board.current?.querySelector<HTMLElement>(`[data-note-id="${CSS.escape(target.id)}"]`)
    const wanted = target.via ? card?.querySelector<HTMLElement>(`[data-move="${target.via}"]`) : null
    const any = card?.querySelector<HTMLElement>("[data-move]")
    ;(wanted ?? any)?.focus()
  }, [notes])

  const titleOf = (id: ColumnId) => COLUMNS.find((c) => c.id === id)?.title ?? id

  function move(id: string, to: ColumnId, via: "back" | "forward" | null) {
    const note = notes.find((n) => n.id === id)
    if (!note || note.column === to) return
    const count = notes.filter((n) => n.column === to).length + 1
    focus.current = { id, via }
    setNotes((all) => [...all.filter((n) => n.id !== id), { ...note, column: to }])
    setMessage(`Moved “${note.title}” to ${titleOf(to)}. ${titleOf(to)} has ${count} ${count === 1 ? "note" : "notes"}.`)
  }

  function add(column: ColumnId, title: string, label: Label) {
    const next = Math.max(0, ...notes.map((n) => Number(n.id.slice(1)) || 0)) + 1
    setNotes((all) => [...all, { id: `n${next}`, title, label, who: TEAM[0], column }])
    setMessage(`Added “${title}” to ${titleOf(column)}.`)
  }

  return (
    <Root className="flex flex-col gap-6 p-4 sm:p-6 lg:p-8">
      <header className="flex flex-wrap items-end justify-between gap-4">
        <div className="flex max-w-prose flex-col gap-1">
          <div className="flex items-center gap-3">
            <h1 className="font-script text-4xl leading-none font-bold sm:text-5xl">Launch week</h1>
            <Sticker name="rocket" size={64} seed="kanban-rocket" className="hidden shrink-0 sm:block" />
          </div>
          <p className="text-muted-foreground">Six days to the autumn drop. Move a note with its arrows, pick it up and drop it, or write a new one.</p>
        </div>
        <AvatarGroup aria-label="On this board" role="group" className="[&>*+*]:-ms-0.5">
          {TEAM.map((name) => (
            <Avatar key={name}>
              <AvatarFallback name={name} />
            </Avatar>
          ))}
        </AvatarGroup>
      </header>

      <div ref={board} className="grid items-start gap-4 md:grid-cols-3">
        {COLUMNS.map((c) => (
          <Column
            key={c.id}
            id={c.id}
            title={c.title}
            hint={c.hint}
            notes={notes.filter((n) => n.column === c.id)}
            dragging={dragging}
            over={over === c.id}
            onOver={(on) => setOver(on ? c.id : (o) => (o === c.id ? null : o))}
            onMove={move}
            onDragStart={(id, e) => {
              e.dataTransfer.setData("text/plain", id)
              e.dataTransfer.effectAllowed = "move"
              setDragging(id)
            }}
            onDragEnd={() => {
              setDragging(null)
              setOver(null)
            }}
            onDrop={(to, e) => {
              const id = e.dataTransfer.getData("text/plain") || dragging
              setDragging(null)
              if (id) move(id, to, null)
            }}
            onAdd={(title, label) => add(c.id, title, label)}
            onClear={
              c.id === "done"
                ? () => {
                    const n = notes.filter((x) => x.column === "done").length
                    setNotes((all) => all.filter((x) => x.column !== "done"))
                    setMessage(`Cleared ${n} done ${n === 1 ? "note" : "notes"}.`)
                  }
                : undefined
            }
          />
        ))}
      </div>
      <p role="status" aria-label="Board updates" className="sr-only">
        {message}
      </p>
    </Root>
  )
}
